214	        }
215	        if (invoice.getStatus() == InvoiceStatus.VOID) {
216	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
217	        }
218	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
219	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
220	        }
221	        if (!invoice.getStatus().isOwing()) {
222	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
