224	        BigDecimal paid = payments.sumAmountByInvoiceId(invoice.getId()).add(amount);
225	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoice.getId());
226	        BigDecimal settled = paid.add(credited);
